local SanderMaker = {}
local PRODUCTS = {
    simple_wood_sander = { name = "Preprost leseni brusilnik", woodCost = 4, leatherCost = 2, sandCost = 1, time = 4, cost = 150, science = 18, happiness = 1, description = "Preprost leseni brusilnik za glajenje." },
    iron_reinforced_sander = { name = "Železnookrepljen brusilnik", woodCost = 3, ironCost = 2, leatherCost = 2, sandCost = 1, time = 7, cost = 380, science = 28, happiness = 2, prestige = 2, description = "Železnookrepljen brusilnik za trgovce." },
    silver_drum_sander = { name = "Srebrnobobenski brusilnik", woodCost = 3, ironCost = 2, silverCost = 1, leatherCost = 2, sandCost = 1, time = 11, cost = 880, science = 42, happiness = 2, prestige = 6, description = "Srebrnobobenski brusilnik za plemiče." },
    gold_trimmed_sander = { name = "Zlatookrasni brusilnik", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, leatherCost = 2, sandCost = 1, time = 15, cost = 2000, science = 56, happiness = 3, prestige = 14, description = "Zlatookrasni brusilnik za visoke plemiče." },
    jewel_set_sander = { name = "Draguljasta brusilnik", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, leatherCost = 2, sandCost = 1, jewelCost = 1, time = 19, cost = 4400, science = 72, happiness = 5, prestige = 27, description = "Brusilnik z draguljem za visoko plemstvo." },
    royal_grand_sander = { name = "Kraljevski veliki brusilnik", woodCost = 5, ironCost = 3, goldCost = 2, silverCost = 2, leatherCost = 2, sandCost = 1, jewelCost = 2, pearlCost = 2, time = 26, cost = 9500, science = 90, happiness = 12, prestige = 58, description = "Veliki kraljevski brusilnik z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    sander_workshop = { name = "Brusilniška delavnica", cost = { gold = 280, wood = 160, stone = 120, leather = 6, sand = 6 }, upkeep = 6, qualityBonus = 5 },
    machinery_loft = { name = "Strojna podstrešje", cost = { gold = 1000, wood = 320, stone = 280, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_machinist_atelier = { name = "Mojstrski strojniški atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_machinery_palace = { name = "Kraljevska strojna palača", cost = { gold = 11500, wood = 600, stone = 800, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
SanderMaker.woodStock = 20; SanderMaker.ironStock = 12; SanderMaker.leatherStock = 14; SanderMaker.sandStock = 10; SanderMaker.silverStock = 6; SanderMaker.goldStock = 6; SanderMaker.jewelStock = 4; SanderMaker.pearlStock = 4
SanderMaker.productStock = {}; SanderMaker.buildings = {}; SanderMaker.maker = nil; SanderMaker.activeMaking = {}; SanderMaker.totalProducts = 0; SanderMaker.dayTimer = 0
function SanderMaker.init() SanderMaker.woodStock=20; SanderMaker.ironStock=12; SanderMaker.leatherStock=14; SanderMaker.sandStock=10; SanderMaker.silverStock=6; SanderMaker.goldStock=6; SanderMaker.jewelStock=4; SanderMaker.pearlStock=4; SanderMaker.productStock={}; SanderMaker.buildings={}; SanderMaker.maker=nil; SanderMaker.activeMaking={}; SanderMaker.totalProducts=0; SanderMaker.dayTimer=0; print("[SanderMaker] Royal Sander Maker System initialized (6 products, 4 buildings)") end
function SanderMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SanderMaker.maker={name=n or ("Brusilnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Brusilnikar najet: %s (spretnost: %d)",SanderMaker.maker.name,s),"success") end; return true end
function SanderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SanderMaker.build(id) local ok,e=SanderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SanderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SanderMaker.getQualityBonus() local b=0; for _,bd in ipairs(SanderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SanderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and SanderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and SanderMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.leatherCost and SanderMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.sandCost and SanderMaker.sandStock<(d.sandCost or 0) then return false,"Premalo peska" end; if d.silverCost and SanderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SanderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SanderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SanderMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SanderMaker.buildings==0 then return false,"Potrebna brusilniška delavnica" end; if not SanderMaker.maker then return false,"Potreben brusilnikar" end; return true end
function SanderMaker.make(pt,qty) qty=qty or 1; local ok,e=SanderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then SanderMaker.woodStock=SanderMaker.woodStock-d.woodCost*qty end; if d.ironCost then SanderMaker.ironStock=SanderMaker.ironStock-d.ironCost*qty end; if d.leatherCost then SanderMaker.leatherStock=SanderMaker.leatherStock-d.leatherCost*qty end; if d.sandCost then SanderMaker.sandStock=SanderMaker.sandStock-d.sandCost*qty end; if d.silverCost then SanderMaker.silverStock=SanderMaker.silverStock-d.silverCost*qty end; if d.goldCost then SanderMaker.goldStock=SanderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SanderMaker.jewelStock=SanderMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SanderMaker.pearlStock=SanderMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SanderMaker.maker then t=math.max(1,t-math.floor(SanderMaker.maker.skill/13)) end; table.insert(SanderMaker.activeMaking,{id="sander_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SanderMaker.completeMaking(m) local q=1.0+(SanderMaker.getQualityBonus()/100); if SanderMaker.maker then q=q+(SanderMaker.maker.skill/140) end; q=math.min(2.5,q); SanderMaker.productStock[m.productType]=(SanderMaker.productStock[m.productType] or 0)+m.quantity; SanderMaker.totalProducts=SanderMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SanderMaker.maker then SanderMaker.maker.itemsMade=SanderMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SanderMaker.maker.skill=math.min(100,SanderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Brusilnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sander.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function SanderMaker.update(dt) if not _G.state then return end; SanderMaker.dayTimer=SanderMaker.dayTimer+dt; if SanderMaker.dayTimer>=30 then SanderMaker.dayTimer=0; for i=#SanderMaker.activeMaking,1,-1 do local m=SanderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SanderMaker.completeMaking(m); table.remove(SanderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SanderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SanderMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SanderMaker.getStats() return {woodStock=SanderMaker.woodStock,ironStock=SanderMaker.ironStock,leatherStock=SanderMaker.leatherStock,sandStock=SanderMaker.sandStock,silverStock=SanderMaker.silverStock,goldStock=SanderMaker.goldStock,jewelStock=SanderMaker.jewelStock,pearlStock=SanderMaker.pearlStock,productStock=SanderMaker.productStock,numBuildings=#SanderMaker.buildings,hasMaker=SanderMaker.maker~=nil,makerName=SanderMaker.maker and SanderMaker.maker.name or "—",makerSkill=SanderMaker.maker and SanderMaker.maker.skill or 0,activeMaking=#SanderMaker.activeMaking,totalProducts=SanderMaker.totalProducts} end
return SanderMaker
